arguments.content:
/* WellStream Platform - Dark Professional Theme */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --primary-navy: #0D1B2A;
  --secondary-navy: #1B2838;
  --accent-blue: #00B4D8;
  --accent-teal: #0077B6;
  --accent-green: #6CC24A;
  --text-white: #FFFFFF;
  --text-light: #E0E0E0;
  --text-muted: #8B9CAF;
  --border-color: #2A3F54;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background-color: var(--primary-navy);
  color: var(--text-light);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border-color);
}

.nav-container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-white);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav-logo span {
  color: var(--accent-blue);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-dropdown {
  position: relative;
}

.nav-dropdown-btn {
  background: transparent;
  border: none;
  color: var(--text-light);
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.5rem;
  transition: color 0.2s;
}

.nav-dropdown-btn:hover {
  color: var(--accent-blue);
}

.nav-dropdown-content {
  position: absolute;
  top: 100%;
  left: 0;
  background: var(--secondary-navy);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 0.5rem;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-10px);
  transition: all 0.2s ease;
  box-shadow: 0 10px 40px rgba(0,0,0,0.4);
}

.nav-dropdown:hover .nav-dropdown-content {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.nav-dropdown-content a {
  display: block;
  padding: 0.75rem 1rem;
  color: var(--text-light);
  text-decoration: none;
  border-radius: 6px;
  transition: all 0.2s;
}

.nav-dropdown-content a:hover {
  background: rgba(0, 180, 216, 0.1);
  color: var(--accent-blue);
}

.nav-link {
  color: var(--text-light);
  text-decoration: none;
  font-size: 0.95rem;
  font-weight: 500;
  transition: color 0.2s;
}

.nav-link:hover {
  color: var(--accent-blue);
}

.nav-cta {
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-teal));
  color: var(--text-white);
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.3s;
  box-shadow: 0 4px 15px rgba(0, 180, 216, 0.3);
}

.nav-cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 25px rgba(0, 180, 216, 0.4);
}

.mobile-menu-btn {
  display: none;
  background: transparent;
  border: none;
  color: var(--text-white);
  cursor: pointer;
  padding: 0.5rem;
}

/* Hero Section */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: 120px 2rem 80px;
  background: linear-gradient(135deg, var(--primary-navy) 0%, var(--secondary-navy) 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: radial-gradient(ellipse at 30% 20%, rgba(0, 180, 216, 0.08) 0%, transparent 50%),
              radial-gradient(ellipse at 80% 80%, rgba(0, 119, 182, 0.06) 0%, transparent 50%);
}

.hero-container {
  max-width: 1400px;
  margin: 0 auto;
  width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  position: relative;
  z-index: 1;
}

.hero-content h1 {
  font-size: 3.5rem;
  font-weight: 800;
  color: var(--text-white);
  line-height: 1.1;
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
}

.hero-content h1 span {
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-teal));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-content p {
  font-size: 1.25rem;
  color: var(--text-muted);
  margin-bottom: 2rem;
  max-width: 540px;
}

.hero-btns {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.btn-primary {
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-teal));
  color: var(--text-white);
  padding: 1rem 2rem;
  border-radius: 8px;
  font-weight: 600;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.3s;
  box-shadow: 0 4px 20px rgba(0, 180, 216, 0.3);
  border: none;
  cursor: pointer;
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 30px rgba(0, 180, 216, 0.4);
}

.btn-secondary {
  background: transparent;
  color: var(--text-white);
  padding: 1rem 2rem;
  border-radius: 8px;
  font-weight: 600;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  border: 1px solid var(--border-color);
  transition: all 0.3s;
}

.btn-secondary:hover {
  border-color: var(--accent-blue);
  background: rgba(0, 180, 216, 0.05);
}

/* Hero Diagram */
.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
}

.platform-diagram {
  width: 100%;
  max-width: 550px;
}

.platform-diagram svg {
  width: 100%;
  height: auto;
}

/* Featured Banner */
.featured-banner {
  background: linear-gradient(90deg, var(--secondary-navy), var(--primary-navy));
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  padding: 1.5rem 2rem;
}

.featured-container {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}

.featured-product {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.featured-badge {
  background: rgba(108, 194, 74, 0.15);
  color: var(--accent-green);
  padding: 0.35rem 0.75rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.featured-name {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-white);
}

.featured-tagline {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.btn-learn {
  color: var(--accent-blue);
  text-decoration: none;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  transition: gap 0.2s;
}

.btn-learn:hover {
  gap: 0.75rem;
}

/* Section Styling */
.section {
  padding: 100px 2rem;
}

.section-dark {
  background: var(--primary-navy);
}

.section-alt {
  background: var(--secondary-navy);
}

.section-container {
  max-width: 1400px;
  margin: 0 auto;
}

.section-label {
  color: var(--accent-blue);
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 1rem;
}

.section-title {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--text-white);
  margin-bottom: 1rem;
  line-height: 1.2;
}

.section-desc {
  color: var(--text-muted);
  font-size: 1.1rem;
  max-width: 700px;
  margin-bottom: 3rem;
}

/* Industry Tabs */
.industry-tabs {
  margin-bottom: 3rem;
}

.tabs-list {
  display: flex;
  gap: 0.5rem;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.tab-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  padding: 1rem 1.5rem;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  position: relative;
  transition: color 0.2s;
}

.tab-btn::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent-blue);
  transform: scaleX(0);
  transition: transform 0.2s;
}

.tab-btn:hover {
  color: var(--text-light);
}

.tab-btn.active {
  color: var(--accent-blue);
}

.tab-btn.active::after {
  transform: scaleX(1);
}

.tab-content {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Use Cases Grid */
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.use-case-card {
  background: var(--secondary-navy);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 2rem;
  transition: all 0.3s;
}

.use-case-card:hover {
  border-color: var(--accent-blue);
  transform: translateY(-4px);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
}

.use-case-icon {
  width: 48px;
  height: 48px;
  background: rgba(0, 180, 216, 0.1);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  color: var(--accent-blue);
}

.use-case-card h3 {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-white);
  margin-bottom: 0.75rem;
}

.use-case-card p {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.6;
}

/* Platform Ecosystem Diagram */
.diagram-section {
  background: var(--secondary-navy);
}

.diagram-container {
  display: flex;
  justify-content: center;
}

.ecosystem-diagram {
  width: 100%;
  max-width: 900px;
}

.ecosystem-diagram svg {
  width: 100%;
  height: auto;
}

/* Company Culture */
.culture-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.culture-content h2 {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--text-white);
  margin-bottom: 1.5rem;
}

.culture-content p {
  color: var(--text-muted);
  font-size: 1.1rem;
  margin-bottom: 2rem;
}

.culture-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.stat-item {
  text-align: center;
}

.stat-number {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--accent-blue);
  display: block;
}

.stat-label {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.culture-visual {
  position: relative;
}

.culture-visual svg {
  width: 100%;
  max-width: 400px;
}

/* Renewables CTA */
.renewables-cta {
  background: linear-gradient(135deg, rgba(108, 194, 74, 0.1), rgba(0, 180, 216, 0.05));
  border: 1px solid rgba(108, 194, 74, 0.3);
  border-radius: 16px;
  padding: 3rem;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2rem;
  align-items: center;
}

.renewables-cta h3 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-white);
  margin-bottom: 0.75rem;
}

.renewables-cta p {
  color: var(--text-muted);
  font-size: 1rem;
}

.btn-renewables {
  background: var(--accent-green);
  color: var(--primary-navy);
  padding: 1rem 2rem;
  border-radius: 8px;
  font-weight: 600;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.3s;
}

.btn-renewables:hover {
  background: #5fb344;
  transform: translateY(-2px);
}

/* Footer */
.footer {
  background: var(--primary-navy);
  border-top: 1px solid var(--border-color);
  padding: 80px 2rem 40px;
}

.footer-container {
  max-width: 1400px;
  margin: 0 auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 3rem;
  margin-bottom: 4rem;
}

.footer-brand {
  max-width: 300px;
}

.footer-logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-white);
  margin-bottom: 1rem;
}

.footer-logo span {
  color: var(--accent-blue);
}

.footer-brand p {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.6;
}

.footer-col h4 {
  color: var(--text-white);
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 1.5rem;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.75rem;
}

.footer-col a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.95rem;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--accent-blue);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border-color);
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-legal {
  display: flex;
  gap: 2rem;
}

.footer-legal a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.85rem;
  transition: color 0.2s;
}

.footer-legal a:hover {
  color: var(--accent-blue);
}

.footer-portals {
  display: flex;
  gap: 1.5rem;
}

.footer-portals a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.85rem;
  transition: color 0.2s;
}

.footer-portals a:hover {
  color: var(--accent-blue);
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--secondary-navy);
  border-top: 1px solid var(--border-color);
  padding: 1.5rem 2rem;
  z-index: 1001;
  display: none;
  animation: slideUp 0.3s ease;
}

.cookie-banner.show {
  display: block;
}

@keyframes slideUp {
  from { transform: translateY(100%); }
  to { transform: translateY(0); }
}

.cookie-container {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}

.cookie-text {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.cookie-text a {
  color: var(--accent-blue);
  text-decoration: none;
}

.cookie-btns {
  display: flex;
  gap: 1rem;
}

.cookie-btn {
  padding: 0.75rem 1.5rem;
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
}

.cookie-btn.accept {
  background: var(--accent-blue);
  color: var(--text-white);
}

.cookie-btn.accept:hover {
  background: var(--accent-teal);
}

.cookie-btn.decline {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-light);
}

.cookie-btn.decline:hover {
  border-color: var(--text-muted);
}

/* Accordion */
.accordion {
  border: 1px solid var(--border-color);
  border-radius: 12px;
  overflow: hidden;
}

.accordion-item {
  border-bottom: 1px solid var(--border-color);
}

.accordion-item:last-child {
  border-bottom: none;
}

.accordion-header {
  width: 100%;
  background: var(--secondary-navy);
  border: none;
  padding: 1.5rem 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  transition: background 0.2s;
}

.accordion-header:hover {
  background: rgba(0, 180, 216, 0.05);
}

.accordion-header h3 {
  color: var(--text-white);
  font-size: 1.1rem;
  font-weight: 600;
  text-align: left;
}

.accordion-icon {
  color: var(--accent-blue);
  transition: transform 0.3s;
}

.accordion-item.active .accordion-icon {
  transform: rotate(180deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  background: var(--primary-navy);
}

.accordion-item.active .accordion-content {
  max-height: 500px;
}

.accordion-body {
  padding: 1.5rem 2rem 2rem;
  color: var(--text-muted);
  line-height: 1.7;
}

/* Stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.stat-card {
  background: var(--secondary-navy);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 2.5rem;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.stat-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-teal));
}

.stat-circle {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  border: 3px solid var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
  position: relative;
}

.stat-circle::after {
  content: '';
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 1px solid rgba(0, 180, 216, 0.3);
}

.stat-value {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--accent-blue);
}

.stat-label {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-top: 0.5rem;
}

/* Timeline */
.timeline {
  position: relative;
  padding-left: 2rem;
}

.timeline::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: linear-gradient(to bottom, var(--accent-blue), var(--accent-teal));
}

.timeline-item {
  position: relative;
  padding-bottom: 2.5rem;
}

.timeline-item::before {
  content: '';
  position: absolute;
  left: -2rem;
  top: 0;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent-blue);
  transform: translateX(-6px);
  box-shadow: 0 0 0 4px rgba(0, 180, 216, 0.2);
}

.timeline-duration {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--accent-blue);
  margin-bottom: 0.25rem;
}

.timeline-title {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--text-white);
  margin-bottom: 0.5rem;
}

.timeline-desc {
  color: var(--text-muted);
  font-size: 0.95rem;
}

.progress-bar {
  height: 6px;
  background: var(--border-color);
  border-radius: 3px;
  margin-top: 1rem;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-teal));
  border-radius: 3px;
  transition: width 0.5s ease;
}

/* Testimonials */
.testimonials-wrapper {
  position: relative;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 100%;
  background: var(--secondary-navy);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 3rem;
}

.testimonial-content {
  font-size: 1.25rem;
  color: var(--text-light);
  line-height: 1.8;
  margin-bottom: 2rem;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.author-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-teal));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-white);
  font-weight: 600;
}

.author-info h4 {
  color: var(--text-white);
  font-size: 1rem;
  font-weight: 600;
}

.author-info p {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 2rem;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-color);
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}

.dot.active {
  background: var(--accent-blue);
  transform: scale(1.2);
}

/* Security Page */
.security-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

.security-features {
  list-style: none;
}

.security-feature {
  background: var(--secondary-navy);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
  margin-bottom: 1rem;
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  transition: all 0.2s;
}

.security-feature:hover {
  border-color: var(--accent-blue);
}

.feature-icon {
  width: 40px;
  height: 40px;
  background: rgba(0, 180, 216, 0.1);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-blue);
  flex-shrink: 0;
}

.feature-content h4 {
  color: var(--text-white);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.feature-content p {
  color: var(--text-muted);
  font-size: 0.9rem;
  line-height: 1.5;
}

.compliance-card {
  background: linear-gradient(135deg, rgba(0, 180, 216, 0.1), rgba(0, 119, 182, 0.05));
  border: 1px solid rgba(0, 180, 216, 0.3);
  border-radius: 16px;
  padding: 2.5rem;
}

.compliance-card h3 {
  color: var(--text-white);
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.compliance-card p {
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.compliance-badges {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.badge {
  background: rgba(0, 180, 216, 0.15);
  color: var(--accent-blue);
  padding: 0.5rem 1rem;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 600;
}

/* Integration Page */
.integration-benefits {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
}

.benefit-card {
  background: var(--secondary-navy);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
  display: flex;
  gap: 1rem;
  align-items: flex-start;
}

.benefit-check {
  width: 24px;
  height: 24px;
  background: rgba(108, 194, 74, 0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-green);
  flex-shrink: 0;
}

.benefit-content h4 {
  color: var(--text-white);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.benefit-content p {
  color: var(--text-muted);
  font-size: 0.9rem;
}

/* Demo Form */
.demo-section {
  min-height: calc(100vh - 72px);
  display: flex;
  align-items: center;
  padding: 120px 2rem 80px;
  background: linear-gradient(135deg, var(--primary-navy) 0%, var(--secondary-navy) 100%);
}

.demo-container {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 4rem;
  align-items: start;
}

.demo-info h1 {
  font-size: 2.75rem;
  font-weight: 700;
  color: var(--text-white);
  margin-bottom: 1rem;
}

.demo-info p {
  color: var(--text-muted);
  font-size: 1.1rem;
  margin-bottom: 2rem;
}

.demo-contact {
  background: var(--secondary-navy);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 1.5rem;
}

.demo-contact h4 {
  color: var(--text-white);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

.demo-contact p {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin-bottom: 0.5rem;
}

.demo-form-card {
  background: var(--secondary-navy);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 2.5rem;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  color: var(--text-light);
  font-size: 0.9rem;
  font-weight: 500;
  margin-bottom: 0.5rem;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  background: var(--primary-navy);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 0.875rem 1rem;
  color: var(--text-white);
